#define IOMMUFD_TYPE ';'
#define IOMMU_IOAS_ALLOC _IO(IOMMUFD_TYPE, 0x81)
#define IOMMU_IOAS_MAP _IO(IOMMUFD_TYPE, 0x85)
#define IOMMU_TEST_CMD _IO(IOMMUFD_TYPE, 0xa0)

struct iommu_ioas_alloc {
    uint32_t size;
    uint32_t flags;
    uint32_t out_ioas_id;
};

struct iommu_test_cmd {
    uint32_t size;
    uint32_t op;
    uint32_t id;
    uint32_t __reserved;
    union {
        struct {
            uint64_t start;
            uint64_t length;
        } add_reserved;
        uint64_t padding[6]; // padding to ensure size is large enough
    };
    uint32_t last;
};

struct iommu_ioas_map {
    uint32_t size;
    uint32_t flags;
    uint32_t ioas_id;
    uint32_t __reserved;
    uint64_t user_va;
    uint64_t length;
    uint64_t iova;
};

int main() {
    int fd = open("/dev/iommu", O_RDWR);
    if (fd < 0) {
        perror("open /dev/iommu");
        return 0; // Don't fail if device not found
    }

    struct iommu_ioas_alloc alloc_cmd = {0};
    alloc_cmd.size = sizeof(alloc_cmd);
    if (ioctl(fd, IOMMU_IOAS_ALLOC, &alloc_cmd) < 0) {
        perror("IOMMU_IOAS_ALLOC");
        return 1;
    }
    printf("Allocated IOAS ID: %u\n", alloc_cmd.out_ioas_id);

    struct iommu_test_cmd test_cmd = {0};
    test_cmd.size = sizeof(test_cmd);
    test_cmd.op = 1; // IOMMU_TEST_OP_ADD_RESERVED
    test_cmd.id = alloc_cmd.out_ioas_id;
    test_cmd.add_reserved.start = 0x6;
    test_cmd.add_reserved.length = 0xffffffffffff8001ULL;

    if (ioctl(fd, IOMMU_TEST_CMD, &test_cmd) < 0) {
        perror("IOMMU_TEST_CMD ADD_RESERVED");
        // If this fails, crash might not happen because condition not met
    }

    void *ptr = mmap(NULL, 0x5000, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    struct iommu_ioas_map map_cmd = {0};
    map_cmd.size = sizeof(map_cmd);
    map_cmd.flags = (1 << 1) | (1 << 2); // WRITEABLE | READABLE
    map_cmd.ioas_id = alloc_cmd.out_ioas_id;
    map_cmd.user_va = (uint64_t)ptr;
    map_cmd.length = 0x5000;

    if (ioctl(fd, IOMMU_IOAS_MAP, &map_cmd) < 0) {
        perror("IOMMU_IOAS_MAP");
        return 1;
    }
    printf("Mapped IOVA: 0x%lx\n", map_cmd.iova);

    return 0;
}

